    foreach(['production_writes_authorized','production_migrations_authorized','deployment_authorized','approved','historical_validation_passed']as$k)if(($packet[$k]??null)!==false)throw new RuntimeException('LEGACY_APPROVAL_PRIVILEGE_ESCALATION');
    if(($packet['blocking_reasons']??null)!==[]||($packet['approval_scope']??'')!=='ATTEST_RECORDED_LEGACY_PER_LOT_TOTALS_ONLY_FOR_ISOLATED_BACKFILL_REHEARSAL_NO_RECALCULATION'||($packet['no_per_cost_per_lot_shares_invented']??null)!==true||($packet['historical_immutable_allocation_not_proven']??null)!==true)throw new RuntimeException('LEGACY_APPROVAL_SCOPE_REJECTED');
    if(array_column($packet['cases']??[],'lot_id')!==array_keys(LEGACY_ALLOCATION_CASES))throw new RuntimeException('LEGACY_APPROVAL_CASE_SET_CHANGED');
    if(count($packet['cases']??[])!==5)throw new RuntimeException('LEGACY_APPROVAL_CASES_REQUIRED');foreach($packet['cases']as$c){$id=$c['lot_id']??0;$scope=LEGACY_ALLOCATION_CASES[$id]??null;if(!$scope||[$c['branch_id'],$c['item_id'],$c['purchase_journal_id']]!==$scope)throw new RuntimeException('LEGACY_APPROVAL_CASE_CHANGED');}
